\title{A Local-to-Global Principle for Coordinate Influence}
\author{Aristotle}
\date{2026-07-09}

\begin{document}
\maketitle

\begin{abstract}
The influence of a coordinate on a Boolean function measures how often flipping
that coordinate changes the function's value. Influence is central to the analysis
of Boolean functions, to hardness of approximation, and to the study of robustness
and diffusion in cryptographic constructions. The Kahn--Kalai--Linial (KKL)
theorem is a \emph{local} statement about a single function: any non-degenerate
function of low total influence must have a coordinate whose influence is unusually
large. In this paper we isolate and prove a complementary \emph{local-to-global}
principle. We show that influence \textbf{self-averages over links}: the global
influence of a coordinate is a weighted average of its influences on the
codimension-one restrictions (links) of the underlying combinatorial object. From
this single identity we derive a family of local-to-global theorems: (i) on the
Boolean cube, a total-influence lower bound on both links of a coordinate forces a
globally influential coordinate; (ii) an abstract averaging engine that runs on any
weighted family of links, converting a \emph{local KKL hypothesis} into a
\emph{global total-influence bound} and a \emph{global influential coordinate};
(iii) a faithful conditional (variance-thresholded) version matching the true
logical shape of KKL; and (iv) an exact total-influence law for regular systems.
The Boolean cube is recovered as a literal instance of the abstract engine.
\end{abstract}

\section{Introduction}

Let $f : \{0,1\}^n \to \{0,1\}$ be a Boolean function. The \emph{influence} of
coordinate $i$ is the number of edges of the Boolean hypercube in direction $i$
whose two endpoints receive different values under $f$. Influences quantify the
sensitivity of a function to individual inputs and are foundational objects in
discrete Fourier analysis, social choice theory, percolation, property testing, and
the theory of pseudorandomness underpinning cryptography.

The Kahn--Kalai--Linial theorem (1988) is the archetypal \emph{local} result: for a
balanced $f$, some coordinate has influence at least $\Omega(\log n / n)$, far
exceeding the average $\TotInf(f)/n$ one would expect under uniform spread. More
generally, KKL guarantees a coordinate of influence $\Omega(\Var(f)\cdot \log n /
n)$.

A distinct modern paradigm is \emph{local-to-global} analysis, central to the theory
of high-dimensional expanders (Bafna--Hoory--Kaufman 2022; Gur--Lifshitz--Liu 2022;
Gotlib--Kaufman 2023). Here one proves properties of a large combinatorial complex
by verifying properties only of its \emph{links} --- the small neighborhoods
obtained by fixing a face. The recurring question is: \emph{if every link satisfies
a property, does the whole complex?}

This paper addresses that question for influence. Our contribution is to identify
the exact structural mechanism --- an averaging identity we call the
\textbf{bridge} --- that transfers influence information from links to the whole
object, and to build a small tower of theorems on top of it.

\section{The concrete model: the Boolean cube and its links}

Throughout, $n \ge 1$ and a point of the cube is $x \in \{0,1\}^n$.

\begin{definition}[Coordinate flip]
For $x \in \{0,1\}^n$ and coordinate $i$, let $x^{\oplus i}$ denote $x$ with its
$i$-th coordinate negated and all other coordinates unchanged. Flipping is an
involution, $(x^{\oplus i})^{\oplus i} = x$, and for $j \ne i$ we have
$(x^{\oplus i})_j = x_j$.
\end{definition}

\begin{definition}[Influence]
The (unnormalized) \emph{influence} of coordinate $i$ on $f$ is
\[
  \Inf(f,i) = \#\{\, x \in \{0,1\}^n : f(x) \ne f(x^{\oplus i}) \,\}.
\]
\end{definition}

\begin{definition}[Link influence]
Fix a coordinate $j$ and value $b \in \{0,1\}$. The \emph{link} of the frozen
vertex $(j,b)$ is the subcube $\{x : x_j = b\}$, a copy of $\{0,1\}^{n-1}$. The
\emph{link influence} of coordinate $i$ is
\[
  \InfSub(f,j,b,i) = \#\{\, x : x_j = b \text{ and } f(x) \ne f(x^{\oplus i}) \,\}.
\]
\end{definition}

\begin{definition}[Total influences]
$\TotInf(f) = \sum_i \Inf(f,i)$, and the \emph{link total influence} is
$\LinkTotInf(f,j,b) = \sum_{i \ne j} \InfSub(f,j,b,i)$.
\end{definition}

\subsection{The bridge}

\begin{theorem}[Influence self-averaging --- the bridge]\label{thm:bridge}
For every function $f$ and every pair of coordinates $j,i$,
\[
  \Inf(f,i) = \InfSub(f,j,0,i) + \InfSub(f,j,1,i).
\]
\end{theorem}
\begin{proof}[Proof sketch]
The set of inputs $x$ with $f(x) \ne f(x^{\oplus i})$ partitions according to the
value of $x_j \in \{0,1\}$; the two parts are counted exactly by $\InfSub(f,j,0,i)$
and $\InfSub(f,j,1,i)$. Formally, split the filtered set by the predicate $x_j = 1$
using $|\{P\}| = |\{P \wedge Q\}| + |\{P \wedge \neg Q\}|$, and identify the pieces
with the link counts.
\end{proof}

\begin{corollary}[Monotonicity]
$\InfSub(f,j,b,i) \le \Inf(f,i)$, since the other summand is non-negative.
\end{corollary}

\begin{theorem}[Total-influence decomposition]\label{thm:linktot}
For every $f$ and coordinate $j$,
\[
  \sum_{i \ne j} \Inf(f,i) = \LinkTotInf(f,j,0) + \LinkTotInf(f,j,1).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Sum the bridge (Theorem~\ref{thm:bridge}) over all $i \ne j$ and regroup.
\end{proof}

\subsection{Pigeonhole and the flagship theorem}

\begin{lemma}[Some element beats the average]\label{lem:avg}
For a finite nonempty set $S$ and $g : S \to \N$, there exists $i \in S$ with
$\sum_{k \in S} g(k) \le |S| \cdot g(i)$.
\end{lemma}
\begin{proof}[Proof sketch]
Take $i$ maximizing $g$; then $\sum_k g(k) \le \sum_k g(i) = |S| \cdot g(i)$.
\end{proof}

\begin{theorem}[Local-to-Global KKL, cube form]\label{thm:cube}
Let $n \ge 2$ and fix a coordinate $j$. Suppose
$T \le \LinkTotInf(f,j,0)$ and $T \le \LinkTotInf(f,j,1)$. Then there exists a
coordinate $i \ne j$ with
\[
  2T \le (n-1)\,\Inf(f,i), \qquad \text{i.e.} \quad \Inf(f,i) \ge \frac{2T}{n-1}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:linktot}, $\sum_{i \ne j}\Inf(f,i) \ge 2T$. The index set
$\{i : i \ne j\}$ has size $n-1 \ge 1$; apply Lemma~\ref{lem:avg} with
$g = \Inf(f,\cdot)$ to obtain $i \ne j$ with $\sum_{i \ne j}\Inf(f,i) \le
(n-1)\Inf(f,i)$. Chain the inequalities.
\end{proof}

\begin{theorem}[Local $\Rightarrow$ global influential coordinate]
If $\tau \le \InfSub(f,j,b,i)$ then $\tau \le \Inf(f,i)$.
\end{theorem}
\begin{proof}[Proof sketch]
Immediate from monotonicity $\InfSub \le \Inf$.
\end{proof}

\section{The abstract local-to-global engine}

Let coordinates be indexed by a finite type and links by a finite type $\kappa$.
Let $w : \kappa \to \R$ be non-negative weights, $I_\ell(i) \ge 0$ the local
influence of coordinate $i$ in link $\ell$, and $I(i)$ the global influence.

\begin{theorem}[Abstract local-to-global KKL]\label{thm:abstract}
Assume $w_\ell \ge 0$, $I_\ell(i) \ge 0$, the \emph{bridge}
$I(i) = \sum_\ell w_\ell I_\ell(i)$ for every $i$, and the \emph{local KKL
hypothesis}: for each $\ell$ there is $i$ with $\tau \le I_\ell(i)$. Then
\[
  \tau \cdot \sum_\ell w_\ell \;\le\; \sum_i I(i).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Exchange summation: $\sum_i I(i) = \sum_\ell w_\ell (\sum_i I_\ell(i))$. For each
$\ell$, the local coordinate $i_0$ gives $\tau \le I_\ell(i_0) \le \sum_i I_\ell(i)$
(a single non-negative term is at most the sum). Hence
$\sum_\ell w_\ell (\sum_i I_\ell(i)) \ge \tau \sum_\ell w_\ell$.
\end{proof}

\begin{lemma}[Real averaging]\label{lem:realavg}
For a nonempty finite index type and $g : \iota \to \R$, there exists $i$ with
$\sum_j g(j) \le |\iota| \cdot g(i)$.
\end{lemma}

\begin{theorem}[Abstract global influential coordinate]\label{thm:abscoord}
Under the hypotheses of Theorem~\ref{thm:abstract}, with the coordinate type
nonempty, there exists $i$ with
$\tau \cdot \sum_\ell w_\ell \le |\text{coords}| \cdot I(i)$.
\end{theorem}
\begin{proof}[Proof sketch]
Combine Theorem~\ref{thm:abstract} with Lemma~\ref{lem:realavg} applied to $g = I$.
\end{proof}

\subsection{The cube as an instance}

\begin{theorem}[Cube via the abstract engine]\label{thm:cubeinstance}
Fix $j$ and $T \in \N$. Suppose $\exists i,\ T \le \InfSub(f,j,0,i)$ and
$\exists i,\ T \le \InfSub(f,j,1,i)$. Then $2T \le \TotInf(f)$.
\end{theorem}
\begin{proof}[Proof sketch]
Instantiate Theorem~\ref{thm:abstract} with $\kappa = \{0,1\}$, unit weights
$w \equiv 1$, $I_\ell(i) = \InfSub(f,j,\ell,i)$, $I(i) = \Inf(f,i)$, $\tau = T$. The
abstract bridge is the concrete bridge (Theorem~\ref{thm:bridge}) summed over the
two Boolean values; $\sum_\ell w_\ell = 2$; and $\sum_i I(i) = \TotInf(f)$.
\end{proof}

\subsection{Faithful conditional and regular systems}

\begin{theorem}[Variance-thresholded local-to-global KKL]
Suppose each link carries a variance proxy $V_\ell$ and threshold $V_0$, with the
local KKL hypothesis in conditional form: if $V_0 \le V_\ell$ then link $\ell$ has a
coordinate of influence $\ge \tau$. If every link is non-degenerate
($V_0 \le V_\ell$ for all $\ell$), then $\tau \sum_\ell w_\ell \le \sum_i I(i)$, and
some coordinate satisfies $\tau \sum_\ell w_\ell \le |\text{coords}| \cdot I(i)$.
\end{theorem}
\begin{proof}[Proof sketch]
Non-degeneracy discharges the conditional on every link, reducing to
Theorems~\ref{thm:abstract} and~\ref{thm:abscoord}.
\end{proof}

\begin{theorem}[Exact law for regular systems]
If every link has the same total influence $\sum_i I_\ell(i) = A$ and every weight
is one, then $\sum_i I(i) = |\kappa| \cdot A$.
\end{theorem}
\begin{proof}[Proof sketch]
By the bridge with unit weights, $\sum_i I(i) = \sum_\ell \sum_i I_\ell(i) =
\sum_\ell A = |\kappa| \cdot A$.
\end{proof}

\begin{theorem}[Cube, real-valued influential coordinate]
For $n \ge 1$, if each of the two links of $j$ has an influential coordinate of
influence $\ge T$, then some global coordinate satisfies $2T \le n \cdot \Inf(f,i)$.
\end{theorem}
\begin{proof}[Proof sketch]
Theorem~\ref{thm:cubeinstance} gives $2T \le \TotInf(f)$; real averaging
(Lemma~\ref{lem:realavg}) over all $n$ coordinates yields the claim.
\end{proof}

\section{Algorithms}

\paragraph{Algorithm A (Influence tabulation).} Given $f$ as a truth table over
$\{0,1\}^n$, compute all $\Inf(f,i)$ and $\InfSub(f,j,b,i)$ by iterating over all
$2^n$ inputs and, for each coordinate, comparing $f(x)$ with $f(x^{\oplus i})$.
Complexity $O(n \cdot 2^n)$.

\paragraph{Algorithm B (Local-to-global certificate).} Given
$T \le \LinkTotInf(f,j,b)$ for both $b$, return the influence-maximizing coordinate
$i \ne j$; it satisfies $2T \le (n-1)\Inf(f,i)$ by Theorem~\ref{thm:cube}.

\section{Applications and discussion}

Influence quantifies output sensitivity to single input bits, so the
local-to-global law certifies sensitivity properties of a function from properties
of its bit-restrictions. The abstract engine consumes exactly the bridge, so any
complex furnishing such a self-averaging identity inherits the theorems, connecting
to the local-to-global program for high-dimensional expanders. The global
conclusions are averaging bounds (max $\ge$ average), tight for the pigeonhole
mechanism but weaker than the full KKL $\Omega(\Var(f)\log n / n)$; bridging that
gap requires Fourier analysis and hypercontractivity (Bonami--Beckner).

\section{Future directions}
\begin{enumerate}
  \item The genuine KKL logarithmic bound via Fourier analysis and
  hypercontractivity.
  \item True simplicial complexes: derive the bridge from the complex structure.
  \item Weighted / spectral links using the spectral gap of links.
  \item Variance transfer: a local-to-global statement for the variance proxy.
  \item Hypercontractivity on high-dimensional expanders as an alternative route.
\end{enumerate}

