"""Demo: verify the bridge identity on random Boolean functions."""
from __future__ import annotations
import random
from itertools import product
from typing import Callable, List, Tuple

Point = Tuple[int, ...]


def flip(x: Point, i: int) -> Point:
    y = list(x); y[i] = 1 - y[i]; return tuple(y)


def points(n: int) -> List[Point]:
    return [tuple(b) for b in product((0, 1), repeat=n)]


def influence(f: Callable[[Point], int], n: int, i: int) -> int:
    return sum(1 for x in points(n) if f(x) != f(flip(x, i)))


def link_influence(f: Callable[[Point], int], n: int, j: int, b: int, i: int) -> int:
    return sum(1 for x in points(n) if x[j] == b and f(x) != f(flip(x, i)))


def random_function(n: int, seed: int) -> Callable[[Point], int]:
    rng = random.Random(seed)
    table = {x: rng.randint(0, 1) for x in points(n)}
    return lambda x: table[x]


def main() -> None:
    for seed in range(5):
        n = 4
        f = random_function(n, seed)
        ok = all(
            influence(f, n, i)
            == link_influence(f, n, 0, 0, i) + link_influence(f, n, 0, 1, i)
            for i in range(n)
        )
        print(f"seed={seed}: bridge holds = {ok}")


if __name__ == "__main__":
    main()

"""Demo: the flagship local-to-global cube theorem on named functions."""
from __future__ import annotations
from itertools import product
from typing import Callable, List, Tuple

Point = Tuple[int, ...]


def flip(x: Point, i: int) -> Point:
    y = list(x); y[i] = 1 - y[i]; return tuple(y)


def points(n: int) -> List[Point]:
    return [tuple(b) for b in product((0, 1), repeat=n)]


def influence(f: Callable[[Point], int], n: int, i: int) -> int:
    return sum(1 for x in points(n) if f(x) != f(flip(x, i)))


def link_total_influence(f: Callable[[Point], int], n: int, j: int, b: int) -> int:
    return sum(
        1
        for i in range(n) if i != j
        for x in points(n) if x[j] == b and f(x) != f(flip(x, i))
    )


def check(name: str, f: Callable[[Point], int], n: int, j: int) -> None:
    T = min(link_total_influence(f, n, j, 0), link_total_influence(f, n, j, 1))
    best = max((influence(f, n, i), i) for i in range(n) if i != j)
    inf_i, i = best
    print(f"{name}: T={T}, witness i={i}, Inf={inf_i}; "
          f"2T={2*T} <= (n-1)Inf={(n-1)*inf_i}: {2*T <= (n-1)*inf_i}")


def main() -> None:
    check("majority-3", lambda x: 1 if sum(x)*2 >= 3 else 0, 3, 0)
    check("parity-4", lambda x: sum(x) % 2, 4, 0)
    check("tribes-4", lambda x: int((x[0] and x[1]) or (x[2] and x[3])), 4, 0)


if __name__ == "__main__":
    main()

"""Demo: the exact total-influence law for regular systems (parity)."""
from __future__ import annotations
from itertools import product
from typing import List, Tuple

Point = Tuple[int, ...]


def flip(x: Point, i: int) -> Point:
    y = list(x); y[i] = 1 - y[i]; return tuple(y)


def points(n: int) -> List[Point]:
    return [tuple(b) for b in product((0, 1), repeat=n)]


def total_influence_parity(n: int) -> int:
    f = lambda x: sum(x) % 2
    return sum(
        1 for i in range(n) for x in points(n) if f(x) != f(flip(x, i))
    )


def main() -> None:
    for n in range(2, 7):
        tot = total_influence_parity(n)
        print(f"n={n}: TotInf(parity)={tot}, predicted n*2^n={n*2**n}, "
              f"match={tot == n*2**n}")


if __name__ == "__main__":
    main()

