from __future__ import annotations
from itertools import product
from typing import Callable, Dict, List, Tuple

Point = Tuple[int, ...]


def all_points(n: int) -> List[Point]:
    return [tuple(b) for b in product((0, 1), repeat=n)]


def flip(x: Point, i: int) -> Point:
    y = list(x); y[i] = 1 - y[i]; return tuple(y)


def tabulate_influences(
    f: Callable[[Point], int], n: int
) -> Tuple[Dict[int, int], Dict[Tuple[int, int, int], int]]:
    """Return (global influences, link influences) for all coordinates/links."""
    glob: Dict[int, int] = {i: 0 for i in range(n)}
    link: Dict[Tuple[int, int, int], int] = {}
    for j in range(n):
        for b in (0, 1):
            for i in range(n):
                link[(j, b, i)] = 0
    for x in all_points(n):
        for i in range(n):
            if f(x) != f(flip(x, i)):
                glob[i] += 1
                for j in range(n):
                    link[(j, x[j], i)] += 1
    return glob, link

