"""Visualization: total influence vs. the local-to-global lower bound 2T."""
from __future__ import annotations
from itertools import product
from typing import Callable, List, Tuple
import matplotlib.pyplot as plt

Point = Tuple[int, ...]


def flip(x: Point, i: int) -> Point:
    y = list(x); y[i] = 1 - y[i]; return tuple(y)


def points(n: int) -> List[Point]:
    return [tuple(b) for b in product((0, 1), repeat=n)]


def influence(f: Callable[[Point], int], n: int, i: int) -> int:
    return sum(1 for x in points(n) if f(x) != f(flip(x, i)))


def link_total(f: Callable[[Point], int], n: int, j: int, b: int) -> int:
    return sum(1 for i in range(n) if i != j for x in points(n)
               if x[j] == b and f(x) != f(flip(x, i)))


def main() -> None:
    n, j = 4, 0
    fns = {"parity": lambda x: sum(x) % 2,
           "majority": lambda x: 1 if 2*sum(x) >= n else 0,
           "tribes": lambda x: int((x[0] and x[1]) or (x[2] and x[3]))}
    names, twoT, avg = [], [], []
    for name, f in fns.items():
        T = min(link_total(f, n, j, 0), link_total(f, n, j, 1))
        best = max(influence(f, n, i) for i in range(n) if i != j)
        names.append(name); twoT.append(2 * T); avg.append((n - 1) * best)
    x = range(len(names))
    fig, ax = plt.subplots(figsize=(8, 5))
    ax.bar([i - 0.2 for i in x], twoT, width=0.4, label="2T (local guarantee)")
    ax.bar([i + 0.2 for i in x], avg, width=0.4, label="(n-1)*max Inf (global)")
    ax.set_xticks(list(x)); ax.set_xticklabels(names)
    ax.set_title("Local-to-global: 2T <= (n-1)*Inf(f,i)")
    ax.legend(); fig.tight_layout(); fig.savefig("local_to_global.png", dpi=150)
    print("saved local_to_global.png")


if __name__ == "__main__":
    main()
